import { useState } from "react";
import { FilterPill, FilterPillGroup } from "@/components/ui/FilterPill";

export function CategoryFilterExample() {
  const [selectedCategory, setSelectedCategory] = useState("all");

  const categories = [
    { value: "all", label: "All Works", count: 42 },
    { value: "electroacoustic", label: "Electroacoustic", count: 18 },
    { value: "choral", label: "Choral", count: 12 },
    { value: "solo-piano", label: "Solo Piano", count: 12 },
  ];

  return (
    <FilterPillGroup
      eyebrow="FILTER ARCHIVE"
      label="Composition Type"
      options={categories}
      value={selectedCategory}
      onChange={setSelectedCategory}
      variant="pill"
    />
  );
}

export function GallerySortExample() {
  const [sortBy, setSortBy] = useState("recent");

  return (
    <div className="flex items-center gap-4">
      <span className="font-sans text-xs font-medium uppercase tracking-widest text-muted-foreground">
        SORT:
      </span>
      <FilterPillGroup
        variant="sort"
        value={sortBy}
        onChange={setSortBy}
        options={[
          { value: "recent", label: "Recently Added" },
          { value: "title", label: "Title" },
          { value: "duration", label: "Duration" },
        ]}
      />
    </div>
  );
}

